<template><div class="page-card" v-loading="loading"><div class="detail-toolbar"><el-button :icon="ArrowLeft" @click="router.push('/contracts')">返回合同列表</el-button></div><template v-if="contract"><header class="contract-head"><div><span>合同编号</span><h1>{{contract.code}}</h1><p>{{contract.merchantName}}</p></div><el-tag :type="statusTagType(contract.status)" size="large">{{contract.status}}</el-tag></header><div class="progress-sheet"><div><span>合同总额</span><strong>¥ {{fmtMoney(contract.totalAmount)}}</strong></div><div><span>已收金额</span><strong>¥ {{fmtMoney(received)}}</strong></div><div><span>欠款金额</span><strong class="red">¥ {{fmtMoney(arrears)}}</strong></div><div class="progress-cell"><span>收款进度</span><el-progress :percentage="progress" :color="progress===100?'#3c8c5a':'#16488a'" /></div></div><el-tabs v-model="tab"><el-tab-pane label="合同信息" name="base"><el-descriptions :column="3" border><el-descriptions-item label="签订日期">{{contract.signDate||'-'}}</el-descriptions-item><el-descriptions-item label="起始日期">{{contract.startDate}}</el-descriptions-item><el-descriptions-item label="到期日期">{{contract.endDate}}</el-descriptions-item><el-descriptions-item label="合同年限">{{contract.years}} 年</el-descriptions-item><el-descriptions-item label="合同状态">{{contract.status}}</el-descriptions-item><el-descriptions-item label="备注">{{contract.remark||'-'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane :label="`关联广告牌 ${contract.items?.length||0}`" name="billboards"><el-table :data="contract.items||[]" border><el-table-column prop="billboardCode" label="广告牌编号" width="150"/><el-table-column prop="sectionName" label="所属路段"/><el-table-column label="每年租金" width="150" align="right"><template #default="{row}">¥ {{fmtMoney(row.yearlyPrice)}}</template></el-table-column><el-table-column label="合同期金额" width="160" align="right"><template #default="{row}">¥ {{fmtMoney((row.yearlyPrice||0)*contract.years)}}</template></el-table-column></el-table></el-tab-pane><el-tab-pane label="年度应收与核销" name="receivables"><el-table :data="receivables" border stripe><el-table-column prop="year" label="年度" width="90"/><el-table-column prop="billboardCode" label="广告牌" width="130"/><el-table-column label="应收" width="130" align="right"><template #default="{row}">{{fmtMoney(row.amount)}}</template></el-table-column><el-table-column label="已收" width="130" align="right"><template #default="{row}">{{fmtMoney(row.received)}}</template></el-table-column><el-table-column label="欠款" width="130" align="right"><template #default="{row}"><span class="red">{{fmtMoney(row.amount-row.received)}}</span></template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="router.push(`/receivables/${row.id}`)">详情</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></template><el-empty v-else-if="!loading" description="未找到合同"/></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ArrowLeft}from'@element-plus/icons-vue';import{contractApi,receivableApi}from'../api';import{fmtMoney,statusTagType}from'../utils/format';import type{Contract,Receivable}from'../types';const route=useRoute(),router=useRouter(),loading=ref(false),tab=ref('base'),contract=ref<Contract|null>(null),receivables=ref<Receivable[]>([]);const received=computed(()=>receivables.value.reduce((s,r)=>s+r.received,0)),arrears=computed(()=>receivables.value.reduce((s,r)=>s+r.amount-r.received,0)),progress=computed(()=>contract.value?.totalAmount?Math.min(100,Math.round(received.value/contract.value.totalAmount*100)):0);onMounted(async()=>{loading.value=true;try{const id=Number(route.params.id);contract.value=(await contractApi.list({})).find(r=>r.id===id)||null;if(contract.value)receivables.value=(await receivableApi.list({merchantId:contract.value.merchantId||undefined})).filter(r=>r.contractId===id)}finally{loading.value=false}});
</script>
<style scoped>.detail-toolbar{margin-bottom:14px}.contract-head{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;background:#0f2d52;color:#fff}.contract-head span{color:#abc0d8;font-size:12px}.contract-head h1{margin:5px 0 3px;font-family:Arial,sans-serif;font-size:23px}.contract-head p{color:#d6e1ed}.progress-sheet{display:grid;grid-template-columns:repeat(3,1fr) 1.35fr;border:1px solid #d8e1eb;border-top:0;margin-bottom:16px}.progress-sheet>div{padding:15px 18px;border-right:1px solid #e1e7ef}.progress-sheet>div:last-child{border-right:0}.progress-sheet span,.progress-sheet strong{display:block}.progress-sheet span{color:#788597;font-size:12px}.progress-sheet strong{margin-top:6px;color:#16488a;font-size:19px}.red{color:#c84040!important}.progress-cell .el-progress{margin-top:11px}@media(max-width:800px){.progress-sheet{grid-template-columns:repeat(2,1fr)}}</style>

